113: 			if readErr != io.EOF {
114: 				return 0, readErr
115: 			}
116: 			if int(C.BrotliDecoderIsFinished(r.state)) == 0 {
117: 				return 0, io.ErrUnexpectedEOF
118: 			}
119: 			return 0, io.EOF
120: 		}
121: 		r.in = r.buf[:m]
122: 	}
123: 
124: 	if len(p) == 0 {
125: 		return 0, nil
126: 	}
127: 
128: 	for {
129: 		var written, consumed C.size_t
130: 		var data *C.uint8_t
131: 		if len(r.in) != 0 {
132: 			data = (*C.uint8_t)(&r.in[0])
133: 		}
134: 		result := C.DecompressStream(r.state,
135: 			(*C.uint8_t)(&p[0]), C.size_t(len(p)),
136: 			data, C.size_t(len(r.in)),
