152: 			}
153: 			return n, nil
154: 		case C.BROTLI_DECODER_NEEDS_MORE_INPUT:
155: 		}
156: 
157: 		if len(r.in) != 0 {
158: 			return 0, errInvalidState
159: 		}
160: 
161: 		// Calling r.src.Read may block. Don't block if we have data to return.
